// books, plus the language-role books. The Ministry prints one edition per
// language; these trees keep the official chapter sequence and printed heads,
// translated so the learner reads the same structure in their study language.
// Guides are original teaching notes generated by `createG12LocalizedBook`.
import type { G12UnitInput, G12UnitSpec } from "./g12.js";
