export const G12_BOOK_BASE =
  "https://elearnningcontent.blob.core.windows.net/elearnningcontent/2026_2027/Secondry/Secondry3/Term1/StudentBook/";

interface TranslationLesson {
  title: string;
  concepts: string[];
}

interface TranslationUnit {
  title: string;
  lessons: TranslationLesson[];
}

interface TranslationBook {
  units: TranslationUnit[];
}

function buildVariant(input: {
  language: G12ContentLanguage;
  subject: string;
  grade: string;
  sourceFile: string;
  base: G12UnitSpec[];
  text: TranslationBook;
}) {
  if (input.text.units.length !== input.base.length) {
    throw new Error(`${input.subject} (${input.language}): unit count does not match the Arabic base`);
  }
  const units: G12UnitInput[] = input.base.map((baseUnit, unitIndex) => {
    const translated = input.text.units[unitIndex]!;
    if (translated.lessons.length !== baseUnit.lessons.length) {
      throw new Error(
        `${input.subject} (${input.language}): lesson count does not match in unit ${baseUnit.key}`,
      );
    }
    return {
      key: baseUnit.key,
      title: translated.title,
      lessons: baseUnit.lessons.map((baseLesson, lessonIndex) => {
        const lesson = translated.lessons[lessonIndex]!;
        if (lesson.concepts.length < 2) {
          throw new Error(`${input.subject} (${input.language}): too few concepts in ${baseLesson.key}`);
        }
        return {
          title: lesson.title,
          concepts: lesson.concepts,
          focus:
            input.language === "fr"
              ? `Reliez ces notions aux exemples et aux exercices du manuel officiel de ${input.subject}.`
              : `Use the official ${input.subject} chapter to connect these ideas with worked examples and exam-style questions.`,
        };
      }),
    };
  });
  const book = createG12LocalizedBook({
    subject: input.subject,
    grade: input.grade,
    sourceUrl: `${G12_BOOK_BASE}${input.sourceFile}`,
    units,
    language: input.language,
  });
  return {
    SOURCE_URL: book.BOOK.sourceUrl,
    BOOK: book.BOOK,
    UNITS: book.UNITS,
    isTreeConsistent: book.isTreeConsistent,
    lessonDocument: book.lessonDocument,
  };
}

